package com.example.starter.domain;

/**
 * 替代规则中的一个候选坐标及其在规则内的优先级（从 1 开始，数字越小优先级越高）。
 */
public record SubstitutionCandidate(String coordinate, int priority) {

    public SubstitutionCandidate {
        coordinate = coordinate == null ? "" : coordinate.trim();
        if (coordinate.isEmpty()) {
            throw new IllegalArgumentException("替代候选坐标不能为空");
        }
        if (priority < 1 || priority > 5) {
            throw new IllegalArgumentException("替代候选优先级必须在 1～5 之间: " + priority);
        }
    }
}

package com.example.starter.domain;

import java.time.Instant;
import java.util.List;

/**
 * 一条依赖替代规则：在指定平台上，命中源坐标模式的节点在无法直接解析时，
 * 按优先级（priority 升序）依次尝试候选坐标；effectiveAt（UTC）之前规则不生效。
 *
 * @param id          规则持久化主键（冻结解释用，未持久化时为 0）
 * @param source      原坐标模式
 * @param platform    目标平台
 * @param candidates  1～5 个按优先级排序的候选坐标
 * @param effectiveAt 生效 UTC 时刻
 */
public record SubstitutionRule(
        long id,
        CoordinatePattern source,
        String platform,
        List<SubstitutionCandidate> candidates,
        Instant effectiveAt) {

    public SubstitutionRule {
        platform = platform == null ? "" : platform.trim();
        if (platform.isEmpty()) {
            throw new IllegalArgumentException("目标平台不能为空");
        }
        if (candidates == null || candidates.isEmpty()) {
            throw new IllegalArgumentException("替代候选数量必须在 1～5 之间");
        }
        if (candidates.size() > 5) {
            throw new IllegalArgumentException("替代候选数量必须在 1～5 之间");
        }
        candidates = List.copyOf(candidates);
        if (effectiveAt == null) {
            throw new IllegalArgumentException("生效时刻不能为空");
        }
    }
}

package com.example.starter.domain;

import java.time.Instant;
import java.util.List;

/**
 * 一个版本化的替代策略：规则集合整体激活，policyVersion 单调递增、不可变。
 *
 * @param version   策略版本号（policyVersion）
 * @param createdAt 发布 UTC 时刻
 * @param rules     策略内全部规则（按发布顺序）
 */
public record SubstitutionPolicy(
        long version,
        Instant createdAt,
        List<SubstitutionRule> rules) {

    public SubstitutionPolicy {
        rules = rules == null ? List.of() : List.copyOf(rules);
    }

    /** 尚未发布过任何策略时的空策略（version 为 null 语义由调用方处理）。 */
    public static SubstitutionPolicy empty() {
        return new SubstitutionPolicy(0L, Instant.EPOCH, List.of());
    }
}

package com.example.starter.domain;

import java.util.List;

/**
 * 单个候选坐标在替代尝试中的拒绝原因快照。
 *
 * @param coordinate 候选坐标
 * @param priority   候选在规则内的优先级（1～5）
 * @param reason     稳定机器可读原因：NOT_FOUND/WITHDRAWN/UNAVAILABLE_PLATFORM/
 *                   CONSTRAINT_INCOMPATIBLE/CYCLE/NO_USABLE_VERSION
 */
public record CandidateRejection(String coordinate, int priority, String reason) {
}

package com.example.starter.domain;

import java.util.List;

/**
 * 锁文件中冻结的单个替代步骤解释。
 *
 * @param stepOrder          步骤序号（从 0 开始，按替代发生顺序）
 * @param originalCoordinate 被替代节点的原坐标
 * @param sourcePattern      命中规则的原坐标模式（字面量）
 * @param platform           规则的目标平台
 * @param finalCoordinate    最终采用的坐标
 * @param policyVersion      解析时读取的唯一策略版本号
 * @param rejections         被拒绝候选的快照（按优先级升序）
 */
public record SubstitutionStep(
        int stepOrder,
        String originalCoordinate,
        String sourcePattern,
        String platform,
        String finalCoordinate,
        long policyVersion,
        List<CandidateRejection> rejections) {

    public SubstitutionStep {
        rejections = rejections == null ? List.of() : List.copyOf(rejections);
    }
}

package com.example.starter.domain;

import java.util.List;
import java.util.Map;

/**
 * 一次替代感知解析的结果：精确版本组合与冻结的替代步骤解释。
 *
 * @param versions      最终坐标 -> 精确版本（坐标升序）
 * @param steps         替代步骤（按发生顺序，稳定排序）
 * @param policyVersion 解析时读取的唯一策略版本；从未发布过策略时为 null
 */
public record SubstitutionResult(
        Map<String, Integer> versions,
        List<SubstitutionStep> steps,
        Long policyVersion) {
}

package com.example.starter.domain;

import java.util.Map;
import java.util.Set;

/**
 * 制品版本在各平台上的可用性快照。
 *
 * <p>某制品版本没有任何平台行时，视为在所有平台可用（向后兼容）；
 * 存在平台行时，仅在列出的平台可用。
 */
public record PlatformAvailability(Map<Long, Set<String>> platformsByArtifactId) {

    public PlatformAvailability {
        platformsByArtifactId = platformsByArtifactId == null
                ? Map.of() : Map.copyOf(platformsByArtifactId);
    }

    /** 判断制品版本在目标平台是否可用。 */
    public boolean available(ArtifactVersion artifact, String platform) {
        Set<String> platforms = platformsByArtifactId.get(artifact.id());
        return platforms == null || platforms.isEmpty() || platforms.contains(platform);
    }
}

package com.example.starter.domain;

/**
 * 替代解析业务失败：触发整次锁定 422 的确定性错误（冲突、环、无可用替代等）。
 */
public class SubstitutionFailureException extends RuntimeException {

    public SubstitutionFailureException(String message) {
        super(message);
    }
}

