package com.example.starter.domain;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * 替代感知的锁图解析器。
 *
 * <p>在一致性快照（制品、撤回状态、平台可用性、唯一 policyVersion）上工作：
 * <ol>
 *   <li>先按既有区间规则选版本（区间交集、高版本优先、带回溯），撤回版本与目标平台不可用版本不可选；</li>
 *   <li>仅当某原坐标在当前路径区间内没有任何可直接使用的版本时（选中版本已撤回或平台不可用），
 *       才按当前生效策略、候选优先级依次尝试替代；</li>
 *   <li>每次替代后把新节点放入全图重新求解其完整传递依赖；候选终点自身无可用版本且命中规则时多跳展开；</li>
 *   <li>相同原坐标在整张图中只有一个结论；后续路径提出不同结论、环、约束不相容均确定性 422。</li>
 * </ol>
 */
public final class SubstitutionLockResolver {

    /** 候选拒绝原因：仓库中不存在该坐标的任何版本。 */
    public static final String REASON_NOT_FOUND = "NOT_FOUND";
    /** 候选拒绝原因：该坐标存在版本但全部已撤回。 */
    public static final String REASON_WITHDRAWN = "WITHDRAWN";
    /** 候选拒绝原因：存在未撤回版本但在目标平台全部不可用。 */
    public static final String REASON_UNAVAILABLE_PLATFORM = "UNAVAILABLE_PLATFORM";
    /** 候选拒绝原因：候选版本与已选节点的版本约束不相容。 */
    public static final String REASON_CONSTRAINT_INCOMPATIBLE = "CONSTRAINT_INCOMPATIBLE";
    /** 候选拒绝原因：展开替代环。 */
    public static final String REASON_CYCLE = "CYCLE";
    /** 候选拒绝原因：区间内无可用版本或替代链终点无可用节点。 */
    public static final String REASON_NO_USABLE_VERSION = "NO_USABLE_VERSION";

    private SubstitutionLockResolver() {
    }

    /**
     * 解析锁图。
     *
     * @return 可行组合与冻结解释；不存在与替代无关的可行组合时返回 null
     * @throws SubstitutionFailureException 替代冲突、环、约束不相容等确定性 422
     */
    public static SubstitutionResult resolve(RepositorySnapshot snapshot,
                                             PlatformAvailability availability,
                                             SubstitutionPolicy policy,
                                             String rootName, int rootVersion,
                                             String platform, Instant now) {
        State state = new State(snapshot, availability, policy, platform, now);
        ArtifactVersion root = state.rootVersion(rootName, rootVersion);
        if (root == null || root.withdrawn()) {
            throw new IllegalArgumentException("根制品版本不存在或已撤回: " + rootName + ":" + rootVersion);
        }
        if (!availability.available(root, platform)) {
            throw new SubstitutionFailureException(
                    "根制品版本在目标平台不可用: " + rootName + ":" + rootVersion + " / " + platform);
        }
        state.chosen.put(rootName, root);
        state.decisions.put(rootName, Decision.direct(rootVersion));

        if (!state.solve()) {
            return null;
        }

        TreeMap<String, Integer> versions = new TreeMap<>();
        state.chosen.forEach((coordinate, artifact) -> versions.put(coordinate, artifact.version()));
        List<SubstitutionStep> steps = state.buildSteps();
        Long policyVersion = policy == null ? null : policy.version();
        return new SubstitutionResult(versions, steps, policyVersion);
    }

    // ------------------------------------------------------------------
    // 解析状态与求解主循环
    // ------------------------------------------------------------------

    private static final class State {
        private final RepositorySnapshot snapshot;
        private final PlatformAvailability availability;
        private final SubstitutionPolicy policy;
        private final String platform;
        private final Instant now;

        /** 最终坐标 -> 选中的精确制品版本。 */
        private final TreeMap<String, ArtifactVersion> chosen = new TreeMap<>();
        /** 图中出现过的每个原坐标的唯一结论（按首次结论顺序）。 */
        private final LinkedHashMap<String, Decision> decisions = new LinkedHashMap<>();

        private State(RepositorySnapshot snapshot, PlatformAvailability availability,
                      SubstitutionPolicy policy, String platform, Instant now) {
            this.snapshot = snapshot;
            this.availability = availability;
            this.policy = policy;
            this.platform = platform;
            this.now = now;
        }

        private ArtifactVersion rootVersion(String name, int version) {
            return snapshot.artifacts().getOrDefault(name, List.of()).stream()
                    .filter(a -> a.version() == version)
                    .findFirst()
                    .orElse(null);
        }

        /**
         * 求解主循环：汇总已选节点对未决坐标的区间交集，字典序选一个坐标继续。
         */
        private boolean solve() {
            String next = null;
            int lo = Integer.MAX_VALUE;
            int hi = Integer.MIN_VALUE;

            for (ArtifactVersion artifact : chosen.values()) {
                for (DependencyRange dep : artifact.dependencies()) {
                    Decision existing = decisions.get(dep.name());
                    if (existing == null) {
                        if (next == null || dep.name().compareTo(next) < 0) {
                            next = dep.name();
                            lo = dep.minimumVersion();
                            hi = dep.maximumVersion();
                        } else if (dep.name().equals(next)) {
                            lo = Math.max(lo, dep.minimumVersion());
                            hi = Math.min(hi, dep.maximumVersion());
                        }
                    } else if (existing.substituted) {
                        // 另一条路径对已替代原坐标提出了新区间：结论必须保持一致。
                        absorbSubstitutedRange(existing, dep.minimumVersion(), dep.maximumVersion());
                    } else {
                        ArtifactVersion selected = chosen.get(dep.name());
                        if (selected != null
                                && (selected.version() < dep.minimumVersion()
                                || selected.version() > dep.maximumVersion())) {
                            return false;
                        }
                    }
                }
            }

            if (next == null) {
                return true;
            }
            if (lo > hi) {
                return false;
            }
            return resolveCoordinate(next, lo, hi);
        }

        /**
         * 解析一个未决原坐标：先尝试直接版本；全部不可用时才按策略替代。
         */
        private boolean resolveCoordinate(String coordinate, int lo, int hi) {
            // 直接路径：区间内高版本优先，跳过撤回与平台不可用版本。
            for (ArtifactVersion candidate : snapshot.artifacts().getOrDefault(coordinate, List.of())) {
                if (candidate.version() < lo || candidate.version() > hi) {
                    continue;
                }
                if (candidate.withdrawn() || !availability.available(candidate, platform)) {
                    continue;
                }
                if (!satisfiesChosen(candidate)) {
                    continue;
                }
                TreeMap<String, ArtifactVersion> chosenSnapshot = new TreeMap<>(chosen);
                LinkedHashMap<String, Decision> decisionsSnapshot = new LinkedHashMap<>(decisions);
                chosen.put(coordinate, candidate);
                decisions.put(coordinate, Decision.direct(candidate.version()));
                if (solve()) {
                    return true;
                }
                chosen.clear();
                chosen.putAll(chosenSnapshot);
                decisions.clear();
                decisions.putAll(decisionsSnapshot);
            }

            // 直接无可用版本：查找当前生效规则。
            SubstitutionRule rule = activeRule(coordinate);
            if (rule == null) {
                return false;
            }
            substitute(coordinate, rule, lo, hi);
            return true;
        }

        /**
         * 应用替代规则并多跳展开；所有候选均失败时确定性 422。
         */
        private void substitute(String original, SubstitutionRule rule, int lo, int hi) {
            Hop firstHop = new Hop(original, rule, null);
            Set<String> ancestors = new HashSet<>();
            ancestors.add(original);
            if (!tryChain(original, rule, firstHop, ancestors)) {
                throw new SubstitutionFailureException(
                        "坐标 " + original + " 的全部替代候选均不可用，无法锁定");
            }
            // tryChain 成功时已落定结论，记录首个原坐标的区间上下文。
            Decision rootDecision = decisions.get(original);
            rootDecision.hasRange = true;
            rootDecision.lo = lo;
            rootDecision.hi = hi;
        }

        /**
         * 在一跳上按优先级尝试候选；候选坐标无可用版本且命中规则时继续向下一跳展开。
         *
         * @param currentHop 当前跳（original 已知；target 随选中候选填写）
         * @param ancestors  已遍历的原坐标链，用于坐标环检测
         */
        private boolean tryChain(String current, SubstitutionRule rule,
                                 Hop currentHop, Set<String> ancestors) {
            List<SubstitutionCandidate> ordered = rule.candidates().stream()
                    .sorted(java.util.Comparator.comparingInt(SubstitutionCandidate::priority))
                    .toList();

            for (SubstitutionCandidate candidate : ordered) {
                String target = candidate.coordinate();

                if (formsCycle(current, target, ancestors)) {
                    currentHop.rejections.add(new CandidateRejection(
                            target, candidate.priority(), REASON_CYCLE));
                    continue;
                }

                Decision already = decisions.get(target);
                if (already != null) {
                    if (adoptDecided(current, rule, target, candidate, currentHop, ancestors)) {
                        return true;
                    }
                    continue;
                }

                BestVersion best = bestUsableVersion(target);
                if (best != null) {
                    TreeMap<String, ArtifactVersion> chosenSnapshot = new TreeMap<>(chosen);
                    LinkedHashMap<String, Decision> decisionsSnapshot = new LinkedHashMap<>(decisions);
                    currentHop.target = target;
                    chosen.put(target, best.artifact);
                    decisions.put(target, Decision.direct(best.artifact.version()));
                    List<Hop> chain = chainThrough(currentHop, ancestors);
                    if (commitChain(chain, target) && solve()) {
                        return true;
                    }
                    chosen.clear();
                    chosen.putAll(chosenSnapshot);
                    decisions.clear();
                    decisions.putAll(decisionsSnapshot);
                    currentHop.rejections.add(new CandidateRejection(
                            target, candidate.priority(), REASON_CONSTRAINT_INCOMPATIBLE));
                    continue;
                }

                SubstitutionRule nextRule = activeRule(target);
                if (nextRule != null) {
                    // 多跳：候选坐标自身无可用版本，按其命中规则继续展开。
                    currentHop.target = target;
                    Hop nextHop = new Hop(target, nextRule, null);
                    Set<String> nextAncestors = new HashSet<>(ancestors);
                    nextAncestors.add(target);
                    if (tryChain(target, nextRule, nextHop, nextAncestors)) {
                        return true;
                    }
                    currentHop.rejections.add(new CandidateRejection(
                            target, candidate.priority(), REASON_NO_USABLE_VERSION));
                    continue;
                }

                currentHop.rejections.add(new CandidateRejection(
                        target, candidate.priority(), classifyUnusable(target)));
            }
            return false;
        }

        /**
         * 候选坐标此前已有结论：复用其终点，并把当前跳链落定。
         */
        private boolean adoptDecided(String current, SubstitutionRule rule, String target,
                                     SubstitutionCandidate candidate, Hop currentHop,
                                     Set<String> ancestors) {
            Decision decision = decisions.get(target);
            String endpoint = decision.substituted ? decision.endpoint : target;
            ArtifactVersion endpointVersion = chosen.get(endpoint);
            if (endpointVersion == null) {
                currentHop.rejections.add(new CandidateRejection(
                        target, candidate.priority(), REASON_NO_USABLE_VERSION));
                return false;
            }
            // 终点版本仍须满足已选节点对终点坐标直接声明的区间。
            if (!satisfiesChosen(endpointVersion)) {
                currentHop.rejections.add(new CandidateRejection(
                        target, candidate.priority(), REASON_CONSTRAINT_INCOMPATIBLE));
                return false;
            }
            currentHop.target = target;
            List<Hop> chain = chainThrough(currentHop, ancestors);
            return commitChain(chain, endpoint);
        }

        /**
         * 把一条成功的跳链落定为每个途经原坐标的唯一替代结论。
         */
        private boolean commitChain(List<Hop> chain, String endpoint) {
            for (Hop hop : chain) {
                Decision previous = decisions.get(hop.original);
                if (previous != null && previous.substituted
                        && !previous.endpoint.equals(endpoint)) {
                    // 同一原坐标此前已指向其他终点：路径冲突，确定性失败。
                    throw new SubstitutionFailureException(
                            "同一原坐标在不同路径上得到不同替代结果: " + hop.original);
                }
            }
            for (Hop hop : chain) {
                Decision decision = Decision.substituted(hop, endpoint);
                decisions.put(hop.original, decision);
            }
            return true;
        }

        /**
         * 从当前跳沿 ancestors 重建本次经过的有序跳链（currentHop 为链首）。
         */
        private List<Hop> chainThrough(Hop firstHop, Set<String> ancestors) {
            // ancestors 与逐级调用构造的链一致；调用栈未保留 Hop 列表，
            // 因此由调用方在成功路径上通过 firstHop 反向收集不可行，
            // 这里改为由实例字段显式保存（见 chainStack）。
            List<Hop> chain = new ArrayList<>();
            chain.add(firstHop);
            for (Hop hop : chainStack) {
                if (ancestors.contains(hop.original)) {
                    chain.add(hop);
                }
            }
            return chain;
        }

        /** 多跳尝试期间尚未落定的后续跳栈。 */
        private final List<Hop> chainStack = new ArrayList<>();

        // ------------------------------------------------------------------
        // 冲突与环检测
        // ------------------------------------------------------------------

        /**
         * 后续路径对已替代原坐标提出新的区间：交集仍无直接可用版本才算同一结论；
         * 交集为空或出现可用直接版本都意味着两个路径结论不同，整次 422。
         */
        private void absorbSubstitutedRange(Decision decision, int lo, int hi) {
            int oldLo = decision.hasRange ? decision.lo : 1;
            int oldHi = decision.hasRange ? decision.hi : Integer.MAX_VALUE;
            int newLo = Math.max(oldLo, lo);
            int newHi = Math.min(oldHi, hi);
            if (newLo > newHi) {
                throw new SubstitutionFailureException(
                        "替代后版本约束不相容：原坐标 " + decision.hop.original
                                + " 的路径区间交集为空");
            }
            if (!decision.hasRange) {
                decision.hasRange = true;
                decision.lo = lo;
                decision.hi = hi;
                return;
            }
            boolean previouslyUnusable = !hasDirectUsable(decision.hop.original, oldLo, oldHi);
            boolean nowUsable = hasDirectUsable(decision.hop.original, newLo, newHi);
            if (previouslyUnusable && nowUsable) {
                throw new SubstitutionFailureException(
                        "两个路径对原坐标 " + decision.hop.original + " 提出了不同替代结论");
            }
            decision.lo = newLo;
            decision.hi = newHi;
        }

        private boolean hasDirectUsable(String coordinate, int lo, int hi) {
            for (ArtifactVersion candidate : snapshot.artifacts().getOrDefault(coordinate, List.of())) {
                if (candidate.version() < lo || candidate.version() > hi) {
                    continue;
                }
                if (!candidate.withdrawn() && availability.available(candidate, platform)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * 加入边 current → target 后是否形成坐标环：
         * 沿已落定结论的替代边与当前链上的跳，target 能否回到 current。
         */
        private boolean formsCycle(String current, String target, Set<String> ancestors) {
            if (target.equals(current) || ancestors.contains(target)) {
                return true;
            }
            Map<String, String> edges = new HashMap<>();
            for (Decision decision : decisions.values()) {
                if (decision.substituted) {
                    edges.put(decision.hop.original, decision.hop.target);
                }
            }
            for (Hop hop : chainStack) {
                if (hop.target != null) {
                    edges.put(hop.original, hop.target);
                }
            }
            String node = edges.get(target);
            Set<String> seen = new HashSet<>();
            while (node != null && seen.add(node)) {
                if (node.equals(current)) {
                    return true;
                }
                node = edges.get(node);
            }
            return false;
        }

        // ------------------------------------------------------------------
        // 规则与候选版本
        // ------------------------------------------------------------------

        /** 查找坐标在当前平台、当前时刻命中的唯一生效规则；无命中返回 null。 */
        private SubstitutionRule activeRule(String coordinate) {
            if (policy == null) {
                return null;
            }
            SubstitutionRule matched = null;
            for (SubstitutionRule rule : policy.rules()) {
                if (!rule.platform().equals(platform)) {
                    continue;
                }
                if (rule.effectiveAt().isAfter(now)) {
                    continue;
                }
                if (rule.source().matches(coordinate)) {
                    if (matched != null) {
                        throw new SubstitutionFailureException(
                                "坐标 " + coordinate + " 命中同优先级冲突规则");
                    }
                    matched = rule;
                }
            }
            return matched;
        }

        /**
         * 为候选坐标挑选当前图约束下最高可用版本；不存在返回 null。
         */
        private BestVersion bestUsableVersion(String coordinate) {
            List<ArtifactVersion> versions = snapshot.artifacts().get(coordinate);
            if (versions == null) {
                return null;
            }
            int lo = Integer.MAX_VALUE;
            int hi = Integer.MIN_VALUE;
            boolean constrained = false;
            for (ArtifactVersion artifact : chosen.values()) {
                for (DependencyRange dep : artifact.dependencies()) {
                    if (dep.name().equals(coordinate)) {
                        constrained = true;
                        lo = Math.min(lo, dep.minimumVersion());
                        hi = Math.max(hi, dep.maximumVersion());
                    }
                }
            }
            // 多个已选节点对同一候选坐标的区间同样取交集。
            lo = Integer.MAX_VALUE;
            hi = Integer.MIN_VALUE;
            for (ArtifactVersion artifact : chosen.values()) {
                for (DependencyRange dep : artifact.dependencies()) {
                    if (dep.name().equals(coordinate)) {
                        lo = Math.max(lo, dep.minimumVersion());
                        hi = Math.min(hi, dep.maximumVersion());
                    }
                }
            }
            for (ArtifactVersion candidate : versions) {
                if (constrained && (candidate.version() < lo || candidate.version() > hi)) {
                    continue;
                }
                if (candidate.withdrawn() || !availability.available(candidate, platform)) {
                    continue;
                }
                if (!satisfiesChosen(candidate)) {
                    continue;
                }
                return new BestVersion(candidate, constrained && lo > hi);
            }
            return null;
        }

        /** 候选坐标无任何可用版本时的稳定拒绝原因分类。 */
        private String classifyUnusable(String coordinate) {
            List<ArtifactVersion> versions = snapshot.artifacts().get(coordinate);
            if (versions == null || versions.isEmpty()) {
                return REASON_NOT_FOUND;
            }
            boolean allWithdrawn = true;
            boolean allUnavailable = true;
            for (ArtifactVersion candidate : versions) {
                if (!candidate.withdrawn()) {
                    allWithdrawn = false;
                }
                if (availability.available(candidate, platform)) {
                    allUnavailable = false;
                }
            }
            if (allWithdrawn) {
                return REASON_WITHDRAWN;
            }
            if (allUnavailable) {
                return REASON_UNAVAILABLE_PLATFORM;
            }
            return REASON_CONSTRAINT_INCOMPATIBLE;
        }

        /**
         * 候选制品对所有已选名称（含自身）声明的区间必须成立。
         */
        private boolean satisfiesChosen(ArtifactVersion candidate) {
            for (DependencyRange dep : candidate.dependencies()) {
                ArtifactVersion selected = chosen.get(dep.name());
                if (selected == null) {
                    continue;
                }
                if (selected.version() < dep.minimumVersion()
                        || selected.version() > dep.maximumVersion()) {
                    return false;
                }
            }
            return true;
        }

        /**
         * 由全部已落定替代结论按发生顺序生成冻结步骤；同一跳链共享终点。
         */
        private List<SubstitutionStep> buildSteps() {
            List<SubstitutionStep> result = new ArrayList<>();
            long policyVersion = policy == null ? 0L : policy.version();
            int order = 0;
            for (Decision decision : decisions.values()) {
                if (!decision.substituted) {
                    continue;
                }
                Hop hop = decision.hop;
                result.add(new SubstitutionStep(order++, hop.original,
                        hop.rule.source().raw(), hop.rule.platform(),
                        decision.endpoint, policyVersion,
                        List.copyOf(hop.rejections)));
            }
            return result;
        }
    }

    private record BestVersion(ArtifactVersion artifact, boolean emptyIntersection) {
    }

    /**
     * 原坐标在本次图解析中的唯一结论。
     */
    private static final class Decision {
        private boolean substituted;
        private int version;
        private Hop hop;
        private String endpoint;
        private boolean hasRange;
        private int lo;
        private int hi;

        private static Decision direct(int version) {
            Decision d = new Decision();
            d.substituted = false;
            d.version = version;
            return d;
        }

        private static Decision substituted(Hop hop, String endpoint) {
            Decision d = new Decision();
            d.substituted = true;
            d.hop = hop;
            d.endpoint = endpoint;
            return d;
        }
    }

    /**
     * 替代链上的一跳：原坐标经某规则指向紧邻的下一个坐标，
     * 以及该跳上按优先级被拒绝的候选。
     */
    private static final class Hop {
        private final String original;
        private final SubstitutionRule rule;
        private String target;
        private final List<CandidateRejection> rejections = new ArrayList<>();

        private Hop(String original, SubstitutionRule rule, String target) {
            this.original = original;
            this.rule = rule;
            this.target = target;
        }
    }
}

